window.MAPS = (window.MAPS||[]).concat([
{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🔀", t:"Zero & First Conditional", es:"Condicional cero y primero", d:"Hechos generales y posibilidades reales en el futuro.",
 boxes:[
  {e:"🧊", h:"Zero conditional", es:"Verdades generales", i:[["If + present, present","Si + presente, presente"],["If you heat ice, it melts.","Si calientas hielo, se derrite."]], ex:["If it rains, the Tube gets very crowded.","Si llueve, el metro se llena mucho."]},
  {e:"🔮", h:"First conditional", es:"Futuro posible", i:[["If + present, will + verb","Si + presente, will + verbo"],["Real possibility","Posibilidad real"]], ex:["If it rains tomorrow, we'll stay in.","Si llueve mañana, nos quedaremos en casa."]},
  {e:"🔄", h:"Order of clauses", es:"Orden de las cláusulas", i:[["If clause first: use a comma","Si empieza con if: coma"],["If clause second: no comma","Si va al final: sin coma"]], ex:["We'll miss the train if we don't hurry.","Perderemos el tren si no nos apuramos."]},
  {e:"🎛️", h:"Other modals", es:"Otros verbos modales", i:[["If + present, can / may / should","Si + presente, can / may / should"],["If + present, imperative","Si + presente, imperativo"]], ex:["If you feel ill, ring the surgery.","Si te encuentras mal, llama al centro de salud."]},
  {e:"🕰️", h:"When / as soon as", es:"Cuando / en cuanto", i:[["when / as soon as + present","when / as soon as + presente"],["Not will after them","Sin will después"]], ex:["I'll ring you as soon as I get home.","Te llamaré en cuanto llegue a casa."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ If it will rain, we'll stay in.","✓ If it rains, we'll stay in. — tras if va presente, no futuro"],["✗ If I will see him, I tell him.","✓ If I see him, I'll tell him. — presente + will"]], ex:["If I see Tom, I'll give him your message.","Si veo a Tom, le daré tu mensaje."]}
 ], qs:[
  {q:"If the bus ____ (be) late, we ____ (walk).", a:"is / will walk — presente + will."},
  {q:"Choose: If you heat water to 100°C, it (boils / will boil).", a:"boils — zero conditional: verdad general."},
  {q:"Correct the mistake: If it will snow tomorrow, we'll build a snowman.", a:"If it snows tomorrow... — no will tras if."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"💭", t:"Second Conditional", es:"Segundo condicional", d:"Situaciones improbables o imaginarias en el presente o futuro.",
 boxes:[
  {e:"🏗️", h:"Form", es:"Estructura", i:[["If + past simple, would + verb","Si + pasado, condicional"],["If I had..., I would...","Si tuviera..., haría..."]], ex:["If I won the lottery, I'd buy a house in Kent.","Si ganara la lotería, compraría una casa en Kent."]},
  {e:"🎯", h:"Use", es:"Cuándo se usa", i:[["Unlikely or impossible","Improbable o imposible"],["Imaginary situations","Situaciones imaginarias"]], ex:["If I lived in London, I'd go to the theatre often.","Si viviera en Londres, iría mucho al teatro."]},
  {e:"🎩", h:"If I were...", es:"Were para todos", i:[["If I were you, I'd...","Yo en tu lugar..."],["If he were here...","Si él estuviera aquí..."]], ex:["If I were you, I'd see a doctor.","Yo en tu lugar, iría al médico."]},
  {e:"💡", h:"Giving advice", es:"Dar consejos", i:[["If I were you, I'd + verb","Yo que tú + condicional"],["I wouldn't do that if I were you.","Yo no haría eso."]], ex:["If I were you, I'd book the train early.","Yo en tu lugar reservaría el tren pronto."]},
  {e:"🔓", h:"Could / might", es:"Otras posibilidades", i:[["If + past, could + verb","Si + pasado, podría"],["If + past, might + verb","Si + pasado, quizá + verbo"]], ex:["If I had a car, I could drive to Bath.","Si tuviera auto, podría manejar hasta Bath."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ If I would have more money, I'd travel.","✓ If I had more money, I'd travel. — pasado simple tras if"],["✗ If I would be you...","✓ If I were you... — nunca would tras if"]], ex:["What would you do if you lost your mobile?","¿Qué harías si perdieras el celular?"]}
 ], qs:[
  {q:"If I ____ (have) more time, I'd learn French.", a:"had — pasado simple tras if."},
  {q:"Choose: If I (am / were) you, I'd ring her.", a:"were — 'If I were you' es el consejo típico."},
  {q:"Correct the mistake: If I would win the lottery, I'd buy a flat.", a:"If I won... — no would en la cláusula if."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"⏪", t:"Third Conditional", es:"Tercer condicional", d:"Situaciones imaginarias en el pasado y sus resultados.",
 boxes:[
  {e:"🏗️", h:"Form", es:"Estructura", i:[["If + past perfect, would have + p.p.","Si + pluscuamperfecto, condicional compuesto"],["If I had known...","Si hubiera sabido..."]], ex:["If I had revised, I would have passed my GCSE.","Si hubiera estudiado, habría aprobado el GCSE."]},
  {e:"🕰️", h:"Use", es:"Pasado irreal", i:[["Imaginary past","Pasado imaginario"],["Can't change it now","Ya no se puede cambiar"]], ex:["If we had left earlier, we wouldn't have missed the train.","Si hubiéramos salido antes, no habríamos perdido el tren."]},
  {e:"😔", h:"Regret", es:"Arrepentimiento", i:[["If only I had...","Ojalá hubiera..."],["I should have + p.p.","Debería haber..."]], ex:["If only I'd taken the umbrella!","¡Ojalá hubiera llevado el paraguas!"]},
  {e:"✂️", h:"Contractions", es:"Contracciones", i:[["I'd = I had / I would","'d = had / would"],["I'd have gone","Habría ido"]], ex:["If she'd told me, I'd have helped.","Si me lo hubiera dicho, la habría ayudado."]},
  {e:"🔓", h:"Might / could have", es:"Posibilidad pasada", i:[["might have + p.p.","quizá habría"],["could have + p.p.","habría podido"]], ex:["If you'd asked, he might have said yes.","Si hubieras preguntado, quizá habría dicho que sí."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ If I would have known, I would have gone.","✓ If I had known, I would have gone. — would solo en la principal"],["✗ If I had know...","✓ If I had known... — participio pasado tras had"]], ex:["If I hadn't missed the bus, I wouldn't have been late.","Si no hubiera perdido el autobús, no habría llegado tarde."]}
 ], qs:[
  {q:"If I ____ (know) about the strike, I ____ (stay) at home.", a:"had known / would have stayed — tercer condicional."},
  {q:"Choose: If she (had studied / would have studied), she'd have passed.", a:"had studied — pluscuamperfecto en la cláusula if."},
  {q:"Correct the mistake: If I would have seen him, I would have said hello.", a:"If I had seen him... — no would tras if."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🧩", t:"Mixed Conditionals", es:"Condicionales mixtos", d:"Combinan pasado y presente en una misma frase condicional.",
 boxes:[
  {e:"🔗", h:"Past → present", es:"Causa pasada, efecto presente", i:[["If + past perfect, would + verb","Si + pluscuamperfecto, would + verbo"],["If I'd left, I'd be home now.","Si me hubiera ido, estaría en casa."]], ex:["If I had studied law, I'd be a solicitor now.","Si hubiera estudiado Derecho, ahora sería abogado."]},
  {e:"↩️", h:"Present → past", es:"Situación actual, efecto pasado", i:[["If + past simple, would have + p.p.","Si + pasado, would have + p.p."],["If I were fitter, I'd have run.","Si estuviera en forma, habría corrido."]], ex:["If I were braver, I'd have spoken to her.","Si fuera más valiente, le habría hablado."]},
  {e:"⏳", h:"Time words", es:"Marcadores de tiempo", i:[["now, today, still","ahora, hoy, todavía"],["last year, yesterday","el año pasado, ayer"]], ex:["If I'd taken that job, I'd live in Leeds now.","Si hubiera aceptado ese trabajo, ahora viviría en Leeds."]},
  {e:"🧬", h:"State verbs", es:"Estados permanentes", i:[["If I were taller...","Si fuera más alto..."],["If I weren't so shy...","Si no fuera tan tímido..."]], ex:["If she weren't so busy, she'd have come.","Si no estuviera tan ocupada, habría venido."]},
  {e:"🆚", h:"Compare types", es:"Comparar tipos", i:[["Second: present/future","Segundo: presente/futuro"],["Third: past/past","Tercero: pasado/pasado"]], ex:["If I'd saved more, I could afford a flat.","Si hubiera ahorrado más, podría permitirme un apartamento."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ If I would have studied, I would be rich.","✓ If I had studied, I would be rich. — had + p.p. en la cláusula if"],["✗ If he had been here, he would have help now.","✓ ...he would be helping now. — efecto presente = would + verbo"]], ex:["If he hadn't moved, he'd still be in Cardiff.","Si no se hubiera mudado, seguiría en Cardiff."]}
 ], qs:[
  {q:"If I ____ (not eat) that curry last night, I ____ (feel) better now.", a:"hadn't eaten / would feel — causa pasada, efecto presente."},
  {q:"Choose: If I were richer, I (would have bought / would buy) it last year.", a:"would have bought — presente en if, resultado pasado."},
  {q:"Correct the mistake: If I had listened, I would not be in trouble yesterday.", a:"...I would not have been in trouble yesterday — ayer = pasado."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🌠", t:"Wish & If only", es:"Wish e If only", d:"Expresar deseos y lamentos sobre presente, pasado y futuro.",
 boxes:[
  {e:"🌍", h:"Present wishes", es:"Deseos del presente", i:[["wish + past simple","wish + pasado"],["I wish I had a car.","Ojalá tuviera auto."]], ex:["I wish I lived nearer the centre.","Ojalá viviera más cerca del centro."]},
  {e:"😞", h:"Past regrets", es:"Lamentos del pasado", i:[["wish + past perfect","wish + pluscuamperfecto"],["I wish I'd studied.","Ojalá hubiera estudiado."]], ex:["I wish I hadn't said that.","Ojalá no hubiera dicho eso."]},
  {e:"😤", h:"Wish + would", es:"Quejas e irritación", i:[["wish + would + verb","wish + would + verbo"],["Not with yourself","No se usa con uno mismo"]], ex:["I wish you would stop talking!","¡Ojalá dejaras de hablar!"]},
  {e:"✨", h:"If only", es:"Más enfático", i:[["If only + past simple","If only + pasado simple"],["If only + past perfect","If only + pluscuamperfecto"]], ex:["If only it would stop raining!","¡Ojalá dejara de llover!"]},
  {e:"🎩", h:"Were", es:"Were con todos", i:[["I wish I were rich.","Ojalá fuera rico."],["I wish she were here.","Ojalá estuviera aquí."]], ex:["I wish it were Friday already.","Ojalá ya fuera viernes."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I wish I have more time.","✓ I wish I had more time. — wish + pasado, no presente"],["✗ I wish I would be taller.","✓ I wish I were taller. — would no va con el propio sujeto"]], ex:["I hope you'll come, but I wish you could stay.","Espero que vengas, pero ojalá pudieras quedarte."]}
 ], qs:[
  {q:"I wish I ____ (not forget) my keys this morning.", a:"hadn't forgotten — lamento del pasado."},
  {q:"Choose: I wish it (stops / would stop) raining.", a:"would stop — queja sobre algo ajeno."},
  {q:"Correct the mistake: I wish I have a bigger flat.", a:"I wish I had... — wish + pasado simple."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🔒", t:"Unless, As long as, Provided that", es:"Unless, as long as, provided that", d:"Conectores que expresan condiciones especiales.",
 boxes:[
  {e:"🚫", h:"Unless", es:"A menos que", i:[["unless = if ... not","unless = si no"],["Unless you hurry, you'll be late.","A menos que te apures, llegarás tarde."]], ex:["Unless it rains, we'll have a barbecue.","A menos que llueva, haremos una barbacoa."]},
  {e:"✅", h:"As long as", es:"Siempre que", i:[["as long as = on condition","as long as = con la condición de que"],["So long as (formal)","So long as (más formal)"]], ex:["You can borrow my car as long as you drive carefully.","Puedes usar mi auto siempre que manejes con cuidado."]},
  {e:"📜", h:"Provided (that)", es:"Siempre que (formal)", i:[["provided / providing (that)","con tal de que"],["More formal","Más formal que as long as"]], ex:["Entry is free provided that you book online.","La entrada es gratuita siempre que reserves por internet."]},
  {e:"🔡", h:"Verb tense", es:"Tiempo verbal", i:[["Use present, not will","Usa presente, no will"],["Provided it's sunny, we'll go.","Siempre que haga sol, iremos."]], ex:["I'll go provided the weather is fine.","Iré siempre que haga buen tiempo."]},
  {e:"🔁", h:"Rewrite", es:"Reescribir", i:[["If you don't = Unless you","If you don't = Unless you (sin segunda negación)"],["Only if ≈ as long as","Only if ≈ as long as (solo si)"]], ex:["Unless you book, you won't get a seat.","A menos que reserves, no tendrás asiento."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Unless you don't hurry, you'll be late.","✓ Unless you hurry, you'll be late. — unless ya es negativo"],["✗ Unless it will rain, we'll go.","✓ Unless it rains, we'll go. — presente, no will"]], ex:["Unless you phone, I'll assume you're coming.","Si no llamas, supondré que vienes."]}
 ], qs:[
  {q:"Unless you ____ (leave) now, you'll miss the last Tube.", a:"leave — unless + presente simple."},
  {q:"Choose: I'll lend you the money (unless / as long as) you pay me back.", a:"as long as — condición positiva."},
  {q:"Correct the mistake: Unless you don't revise, you'll fail.", a:"Unless you revise... — no doble negación."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"👤", t:"Defining Relative Clauses", es:"Oraciones de relativo especificativas", d:"Información esencial para identificar a quién o qué nos referimos.",
 boxes:[
  {e:"🧑", h:"Who / that", es:"Personas", i:[["the man who lives next door","el hombre que vive al lado"],["the girl that works here","la chica que trabaja aquí"]], ex:["The woman who lives upstairs is a nurse.","La mujer que vive arriba es enfermera."]},
  {e:"📦", h:"Which / that", es:"Cosas", i:[["the book which I bought","el libro que compré"],["the bus that goes to Bath","el autobús que va a Bath"]], ex:["The pub that we visited was lovely.","El pub que visitamos era precioso."]},
  {e:"📍", h:"Where", es:"Lugares", i:[["the town where I was born","la ciudad donde nací"],["the shop where she works","la tienda donde trabaja"]], ex:["This is the café where we met.","Esta es la cafetería donde nos conocimos."]},
  {e:"✂️", h:"Omit the pronoun", es:"Omitir el pronombre", i:[["Object: can leave out","Como objeto: se puede omitir"],["Subject: must keep","Como sujeto: es obligatorio"]], ex:["The film (that) we watched was long.","La película que vimos era larga."]},
  {e:"👑", h:"Whose & prepositions", es:"Whose y preposiciones", i:[["the man whose car was stolen","el hombre cuyo auto robaron"],["the person I spoke to","la persona con quien hablé"]], ex:["That's the girl whose brother plays for Arsenal.","Esa es la chica cuyo hermano juega en el Arsenal."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The film what I saw was good.","✓ The film that I saw was good. — what no es relativo aquí"],["✗ The man who he lives here is Tom.","✓ The man who lives here is Tom. — no repetir el sujeto"]], ex:["The students who cheated were punished.","Los alumnos que hicieron trampas fueron castigados."]}
 ], qs:[
  {q:"That's the man ____ lives opposite us. (who / which)", a:"who — para personas."},
  {q:"Choose: The book (that / what) I borrowed was brilliant.", a:"that — what no sirve como relativo."},
  {q:"Correct the mistake: The girl who she works here is my cousin.", a:"The girl who works here... — sin pronombre repetido."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"➕", t:"Non-defining Relative Clauses", es:"Oraciones de relativo explicativas", d:"Información extra entre comas que no es esencial.",
 boxes:[
  {e:"✍️", h:"Commas", es:"Comas", i:[["Put commas before and after","Comas antes y después"],["Extra information","Información adicional"]], ex:["My brother, who lives in Leeds, is a chef.","Mi hermano, que vive en Leeds, es cocinero."]},
  {e:"🔗", h:"Who, which, where, whose", es:"Pronombres", i:[["who: people","who: personas"],["which: things","which: cosas"],["whose: possession","whose: posesión"]], ex:["Bath, where I studied, is beautiful.","Bath, donde estudié, es preciosa."]},
  {e:"✋", h:"Pronoun stays", es:"El pronombre no se omite", i:[["Can't leave out which/who","No se puede omitir which/who"],["Not even as object","Ni siquiera como objeto"]], ex:["Tom, who I met at uni, is a vet.","Tom, a quien conocí en la universidad, es veterinario."]},
  {e:"📖", h:"Which = whole clause", es:"Which = toda la frase", i:[["..., which surprised me","..., lo cual me sorprendió"],["..., which is why...","..., por eso..."]], ex:["He passed, which surprised everyone.","Aprobó, lo que sorprendió a todos."]},
  {e:"🎩", h:"Prepositions", es:"Preposiciones formales", i:[["to whom, in which","a quien, en el cual"],["Formal writing","Escritura formal"]], ex:["The hotel, in which we stayed, was cheap.","El hotel, en el que nos alojamos, era barato."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The Tower, that is in London, is old.","✓ The Tower, which is in London, is old. — nunca that con comas"],["✗ My mum who is a nurse works hard.","✓ My mum, who is a nurse, works hard. — comas obligatorias"]], ex:["My dad, who works nights, is often tired.","Mi papá, que trabaja de noche, suele estar cansado."]}
 ], qs:[
  {q:"My sister, ____ lives in Cardiff, is a teacher. (who / that)", a:"who — that no se usa entre comas."},
  {q:"Choose: Rome, (where / which) we spent a week, was lovely.", a:"where — lugar con comas."},
  {q:"Correct the mistake: My car, that I bought in May, has broken down.", a:"My car, which I bought... — that no con comas."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"✂️", t:"Reduced Relative Clauses (-ing / -ed)", es:"Relativas reducidas (-ing / -ed)", d:"Acortar oraciones de relativo con participios.",
 boxes:[
  {e:"🏃", h:"-ing: active", es:"-ing: voz activa", i:[["who is standing → standing","que está de pie → standing"],["which runs → running","que corre → running"]], ex:["The man standing at the bus stop is my uncle.","El hombre que está en la parada es mi tío."]},
  {e:"📬", h:"-ed: passive", es:"-ed: voz pasiva", i:[["which was written → written","que fue escrito → written"],["that is made → made","que está hecho → made"]], ex:["The letter sent yesterday hasn't arrived.","La carta enviada ayer no ha llegado."]},
  {e:"🗑️", h:"What we remove", es:"Qué se elimina", i:[["Pronoun + be","Se quita pronombre + be"],["Pronoun + auxiliary","Se quita pronombre + auxiliar"]], ex:["Students taking GCSEs need to revise.","Los alumnos que hacen los GCSE deben estudiar."]},
  {e:"🔁", h:"Habit or state", es:"Hábito o estado", i:[["Buses that go to Bath → Buses going...","Autobuses que van → going"],["Use the -ing form","Se usa la forma -ing"]], ex:["Trains leaving from Platform 4 are delayed.","Los trenes que salen del andén 4 llevan retraso."]},
  {e:"💼", h:"Style", es:"Estilo", i:[["Common in writing","Común en textos escritos"],["Signs and news","Letreros y noticias"]], ex:["Passengers travelling to Kent should change here.","Los pasajeros que viajen a Kent deben cambiar aquí."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The man called me was Tom.","✓ The man who called me was Tom. — acción puntual pasada: no se reduce"],["✗ The books writing by Orwell...","✓ The books written by Orwell... — pasiva = -ed"]], ex:["The man who called earlier was Mr Jones.","El hombre que llamó antes era el Sr. Jones."]}
 ], qs:[
  {q:"The girl ____ (wear) the red coat is my cousin.", a:"wearing — activa reducida."},
  {q:"Choose: The house (building / built) in 1900 is still standing.", a:"built — pasiva: 'que fue construida'."},
  {q:"Correct the mistake: The money stealing from the shop was never found.", a:"The money stolen from the shop... — pasiva = stolen."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"⚖️", t:"Gerund vs Infinitive", es:"Gerundio frente a infinitivo", d:"Algunos verbos cambian de significado según la forma que les sigue.",
 boxes:[
  {e:"🧠", h:"Remember", es:"Recordar", i:[["remember + -ing: recall past","remember + -ing: recordar haber hecho"],["remember + to: not forget","remember + to: acordarse de hacer"]], ex:["I remember locking the door. / Remember to lock it.","Recuerdo haber cerrado. / Acuérdate de cerrar."]},
  {e:"🙈", h:"Forget", es:"Olvidar", i:[["forget + -ing: past memory","forget + -ing: olvidar haber hecho"],["forget + to: omit a task","forget + to: olvidarse de hacer"]], ex:["I'll never forget meeting the King.","Nunca olvidaré haber conocido al rey."]},
  {e:"🛑", h:"Stop", es:"Parar", i:[["stop + -ing: end an action","stop + -ing: dejar de hacer"],["stop + to: pause in order to","stop + to: parar para hacer"]], ex:["We stopped to buy petrol.","Paramos para comprar gasolina."]},
  {e:"🧪", h:"Try", es:"Intentar / probar", i:[["try + to: make an effort","try + to: intentar"],["try + -ing: experiment","try + -ing: probar"]], ex:["Try switching it off and on again.","Prueba apagarlo y volver a encenderlo."]},
  {e:"😢", h:"Regret & go on", es:"Regret y go on", i:[["regret + to: formal news","regret + to: lamentar informar"],["go on + -ing: continue","go on + -ing: continuar haciendo"]], ex:["We regret to inform you that the train is cancelled.","Lamentamos informarles de que el tren está cancelado."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I stopped to smoke last year.","✓ I stopped smoking last year. — dejar de hacer = -ing"],["✗ I remember to post it, I did it.","✓ I remember posting it. — recuerdo haberlo hecho"]], ex:["She went on talking for an hour.","Siguió hablando una hora."]}
 ], qs:[
  {q:"I'll never forget ____ (see) Big Ben for the first time.", a:"seeing — recuerdo del pasado = -ing."},
  {q:"Choose: Remember (posting / to post) that letter on your way.", a:"to post — tarea pendiente."},
  {q:"Correct the mistake: He stopped to eat meat ten years ago.", a:"He stopped eating meat — dejó de comer carne."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"📋", t:"Verb Patterns: -ing vs to + infinitive (lists)", es:"Patrones verbales: -ing y to + infinitivo", d:"Listas de verbos que van seguidos de gerundio o de infinitivo.",
 boxes:[
  {e:"❤️", h:"Verbs + -ing", es:"Verbos + -ing", i:[["enjoy, mind, finish, avoid","disfrutar, importar, terminar, evitar"],["give up, keep, suggest, consider","dejar, seguir, sugerir, considerar"]], ex:["I enjoy walking along the Thames.","Disfruto paseando junto al Támesis."]},
  {e:"🎯", h:"Verbs + to + inf", es:"Verbos + to + infinitivo", i:[["want, hope, plan, decide","querer, esperar, planear, decidir"],["agree, refuse, promise, offer","acordar, negarse, prometer, ofrecer"]], ex:["We've decided to rent a flat in Brighton.","Hemos decidido alquilar un apartamento en Brighton."]},
  {e:"💪", h:"Effort & ability", es:"Esfuerzo y capacidad", i:[["manage, try, fail, afford","conseguir, intentar, no lograr, permitirse"],["seem, appear, learn","parecer, aparentar, aprender"]], ex:["She managed to get a ticket.","Consiguió una entrada."]},
  {e:"🔗", h:"After prepositions", es:"Tras preposiciones", i:[["interested in + -ing","interesado en + -ing"],["look forward to + -ing","tener ganas de + -ing"]], ex:["I'm looking forward to seeing you.","Tengo ganas de verte."]},
  {e:"🔀", h:"Both patterns", es:"Ambos patrones", i:[["like, love, hate, prefer","gustar, amar, odiar, preferir"],["begin, start, continue","empezar, comenzar, continuar"]], ex:["I like cycling / I like to cycle to work.","Me gusta ir en bici al trabajo."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I enjoy to walk in the park.","✓ I enjoy walking in the park. — enjoy + -ing"],["✗ She suggested to go home.","✓ She suggested going home. — suggest + -ing"],["✗ I decided going home.","✓ I decided to go home. — decide + to + infinitivo"]], ex:["He promised to ring me tonight.","Prometió llamarme esta noche."]}
 ], qs:[
  {q:"She suggested ____ (go) to the pub after work.", a:"going — suggest + -ing."},
  {q:"Choose: We can't afford (buying / to buy) a house in London.", a:"to buy — afford + to + infinitivo."},
  {q:"Correct the mistake: I'm looking forward to see you.", a:"to seeing — to es preposición aquí, lleva -ing."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🗣️", t:"Verb + Object + Infinitive (want, ask, tell)", es:"Verbo + objeto + infinitivo", d:"Pedir, querer o mandar a alguien que haga algo.",
 boxes:[
  {e:"🙋", h:"Want / would like", es:"Querer", i:[["want + someone + to + verb","querer que alguien haga algo"],["would like + object + to","me gustaría que + subjuntivo"]], ex:["I want you to meet my mum.","Quiero que conozcas a mi madre."]},
  {e:"🙏", h:"Ask", es:"Pedir", i:[["ask + object + to + verb","pedir a alguien que haga"],["ask for + noun","pedir algo"]], ex:["She asked me to open the window.","Me pidió que abriera la ventana."]},
  {e:"📣", h:"Tell / order", es:"Decir / ordenar", i:[["tell + object + to + verb","decir a alguien que haga"],["order, warn, remind","ordenar, advertir, recordar"]], ex:["The teacher told us to be quiet.","La profesora nos dijo que guardáramos silencio."]},
  {e:"🤗", h:"Allow & help", es:"Permitir y ayudar", i:[["allow / invite / encourage","permitir / invitar / animar"],["help + object + (to) verb","ayudar a alguien a hacer"]], ex:["They invited us to stay for tea.","Nos invitaron a quedarnos a tomar té."]},
  {e:"🚫", h:"Negative", es:"Negativo", i:[["tell + object + not to","decir a alguien que no haga"],["ask + object + not to","pedir que no haga"]], ex:["The doctor told me not to drive.","El médico me dijo que no manejara."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I want that you come.","✓ I want you to come. — no se usa that + subjuntivo"],["✗ She told me that I wait.","✓ She told me to wait. — tell + objeto + to"],["✗ He said me to wait.","✓ He told me to wait. — say no lleva objeto de persona así; tell + objeto + to"]], ex:["I'd like you to wait here, please.","Me gustaría que esperara aquí, por favor."]}
 ], qs:[
  {q:"My boss wants me ____ (finish) the report by 5 pm.", a:"to finish — want + objeto + to."},
  {q:"Choose: The teacher told us (stay / to stay) quiet.", a:"to stay — tell + objeto + to."},
  {q:"Correct the mistake: I want that you help me.", a:"I want you to help me. — want + objeto + to, sin that."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"A2", icon:"📏", t:"Comparatives & Superlatives", es:"Comparativos y superlativos", d:"Comparar dos cosas y expresar el grado máximo dentro de un grupo.",
 boxes:[
  {e:"1️⃣", h:"Short adjectives", es:"Adjetivos cortos", i:[["cheap → cheaper → the cheapest","barato → más barato → el más barato"],["big → bigger → the biggest","grande → más grande → el más grande"]], ex:["Trains are cheaper than taxis.","Los trenes son más baratos que los taxis."]},
  {e:"🔠", h:"Long adjectives", es:"Adjetivos largos", i:[["more + adj + than","más + adj + que"],["the most + adj","el más + adj"]], ex:["London is more expensive than Leeds.","Londres es más caro que Leeds."]},
  {e:"🎭", h:"Irregular", es:"Irregulares", i:[["good → better → the best","bueno → mejor → el mejor"],["bad → worse → the worst","malo → peor → el peor"],["far → further → the furthest","lejos → más lejos → el más lejano"]], ex:["That was the worst film ever.","Fue la peor película de todos los tiempos."]},
  {e:"🔼", h:"Modifiers & patterns", es:"Modificadores y patrones", i:[["much / a bit + comparative","mucho / un poco más"],["The more..., the better","Cuanto más..., mejor"]], ex:["The Tube is much quicker than the bus.","El metro es mucho más rápido que el autobús."]},
  {e:"🌐", h:"Superlative use", es:"Uso del superlativo", i:[["the biggest city in the UK","la ciudad más grande del Reino Unido"],["the best ... I've ever had","el mejor ... que he tenido"]], ex:["It's the best fish and chips I've ever had.","Son los mejores fish and chips que he comido."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ He is more tall than me.","✓ He is taller than me. — adjetivo corto + -er"],["✗ the most cheap","✓ the cheapest — corto + -est, sin most"],["✗ better that","✓ better than — comparativo + than, no that"]], ex:["She's the fastest runner in the school.","Es la corredora más rápida del colegio."]}
 ], qs:[
  {q:"This flat is ____ (small) than my old one.", a:"smaller — corto + -er + than."},
  {q:"Choose: It's (the most good / the best) restaurant in Bristol.", a:"the best — superlativo irregular."},
  {q:"Correct the mistake: Today is more hot than yesterday.", a:"hotter than — adjetivo corto, duplica t."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🟰", t:"As...as & Comparisons (the same as, similar to, different from/to)", es:"As...as y comparaciones", d:"Expresar igualdad, parecido y diferencia.",
 boxes:[
  {e:"🟰", h:"as + adj + as", es:"Igualdad", i:[["as tall as","tan alto como"],["as quickly as possible","lo más rápido posible"]], ex:["My flat is as big as yours.","Mi apartamento es tan grande como el tuyo."]},
  {e:"➖", h:"not as ... as", es:"Menos que", i:[["not as cold as","no tan frío como"],["not so ... as","no tan ... como (más formal)"]], ex:["Bristol isn't as expensive as London.","Bristol no es tan caro como Londres."]},
  {e:"👯", h:"the same as", es:"Lo mismo que", i:[["the same as","igual que"],["the same age as","la misma edad que"]], ex:["Your phone is the same as mine.","Tu celular es igual que el mío."]},
  {e:"🤝", h:"similar to", es:"Parecido a", i:[["similar to","similar a"],["like","como, parecido a"]], ex:["Scottish accents are similar to Irish ones.","Los acentos escoceses se parecen a los irlandeses."]},
  {e:"↔️", h:"different from / to", es:"Diferente de", i:[["different from (standard)","different from (estándar)"],["different to (very British)","different to (muy habitual en UK)"]], ex:["Life here is different from life in Spain.","La vida aquí es distinta de la de España."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ He is as tall than me.","✓ He is as tall as me. — as...as, no than"],["✗ It's same as mine.","✓ It's the same as mine. — the same as"],["✗ different that","✓ different from / to — nunca that"]], ex:["Rent in London is twice as high as in Leeds.","El alquiler en Londres es el doble que en Leeds."]}
 ], qs:[
  {q:"My phone is ____ yours – they're identical. (the same as / similar to)", a:"the same as — idénticos."},
  {q:"Choose: Cardiff isn't (as big than / as big as) London.", a:"as big as — as...as."},
  {q:"Correct the mistake: Her accent is different than mine.", a:"different from / to mine — en UK no 'than'."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🅰️", t:"Articles", es:"Artículos: a / an / the y sin artículo", d:"Cuándo usar a, an, the o ningún artículo.",
 boxes:[
  {e:"1️⃣", h:"A / an", es:"Indefinido", i:[["a + consonant sound","a + sonido consonante"],["an + vowel sound","an + sonido vocal"],["an hour, a university","an hour, a university (cuenta el sonido)"]], ex:["She's an engineer with a degree from Oxford.","Es ingeniera con un título de Oxford."]},
  {e:"🆕", h:"A/an vs the", es:"Nueva información o conocida", i:[["a/an: first mention","a/an: primera mención"],["the: already known / unique","the: ya conocido o único"]], ex:["I bought a jacket. The jacket was cheap.","Compré una chaqueta. La chaqueta era barata."]},
  {e:"🏔️", h:"Names with the", es:"Nombres con the", i:[["the Thames, the Alps","los ríos, cordilleras"],["the UK, the Netherlands","países en plural o con república/reino"]], ex:["We sailed down the Thames.","Navegamos por el Támesis."]},
  {e:"🌍", h:"Zero article", es:"Sin artículo", i:[["Dogs are loyal. I like music.","Generalizaciones: plural e incontable"],["have breakfast, by bus, in France","comidas, transporte, países"]], ex:["Children need love and sleep.","Los niños necesitan cariño y sueño."]},
  {e:"🏥", h:"Institutions (UK)", es:"Instituciones", i:[["in hospital, at university","ingresado, en la universidad"],["in prison, at school","en la cárcel, en el colegio"]], ex:["My dad is in hospital.","Mi padre está en el hospital."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The life is expensive.","✓ Life is expensive. — generalización: sin the"],["✗ I have a breakfast at 8.","✓ I have breakfast at 8. — comidas sin artículo"],["✗ She is teacher.","✓ She is a teacher. — profesión con a"]], ex:["I'm at home at the weekend.","Estoy en casa el fin de semana."]}
 ], qs:[
  {q:"She's ____ honest person. (a / an)", a:"an — honest empieza con sonido vocal."},
  {q:"Choose: My brother is in (hospital / the hospital) after an accident.", a:"hospital — en UK, sin the como paciente."},
  {q:"Correct the mistake: I go to work by the bus.", a:"by bus — transporte sin artículo."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🔢", t:"Quantifiers (some, any, much, many, a lot of, few, little)", es:"Cuantificadores", d:"Expresar cantidades con nombres contables e incontables.",
 boxes:[
  {e:"✅", h:"Some", es:"Some: afirmativo", i:[["some + plural / uncountable","some + plural / incontable"],["Offers and requests","Ofrecimientos y peticiones"]], ex:["Would you like some tea?","¿Quieres un poco de té?"]},
  {e:"❓", h:"Any", es:"Any: negativo y pregunta", i:[["not any","no ... ningún"],["Have you got any...?","¿Tienes algún...?"]], ex:["We haven't got any milk.","No tenemos leche."]},
  {e:"🍞", h:"Much / many", es:"Much / many", i:[["many + countable","many + contable"],["much + uncountable","much + incontable"]], ex:["How much money? How many biscuits?","¿Cuánto dinero? ¿Cuántas galletas?"]},
  {e:"💯", h:"A lot of", es:"A lot of", i:[["a lot of: both types","a lot of: sirve para ambos"],["Best in affirmatives","Mejor en afirmativas"]], ex:["There are a lot of tourists in London.","Hay muchos turistas en Londres."]},
  {e:"🤏", h:"Few / little", es:"Pocos", i:[["a few + countable","a few + contable (algunos)"],["a little + uncountable","a little + incontable (un poco)"],["few / little: almost none","few / little: casi nada, tono negativo"]], ex:["I've got a few friends in Leeds.","Tengo algunos amigos en Leeds."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I have many money.","✓ I have a lot of money. — money es incontable"],["✗ There aren't some chairs.","✓ There aren't any chairs. — negativo = any"],["✗ How much people?","✓ How many people? — people es contable"]], ex:["There's little time left, so hurry.","Queda poco tiempo, así que apúrate."]}
 ], qs:[
  {q:"There isn't ____ milk in the fridge. (some / any)", a:"any — negativo."},
  {q:"Choose: How (much / many) homework have you got?", a:"much — homework es incontable."},
  {q:"Correct the mistake: I have many informations about the course.", a:"much information — information es incontable."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🥛", t:"Countable & Uncountable Nouns", es:"Nombres contables e incontables", d:"Distinguir sustantivos que se pueden contar de los que no.",
 boxes:[
  {e:"🍎", h:"Countable", es:"Contables", i:[["a/an, plural -s","a/an, plural en -s"],["an apple, two apples","una manzana, dos manzanas"]], ex:["I bought three apples at the market.","Compré tres manzanas en el mercado."]},
  {e:"💧", h:"Uncountable", es:"Incontables", i:[["no plural, no a/an","sin plural ni a/an"],["water, rice, money","agua, arroz, dinero"]], ex:["The water in London is hard.","El agua de Londres es dura."]},
  {e:"🧳", h:"Tricky nouns", es:"Nombres difíciles", i:[["advice, information, news","consejo, información, noticias"],["luggage, furniture, traffic","equipaje, muebles, tráfico"]], ex:["The news is good today.","Las noticias son buenas hoy."]},
  {e:"📏", h:"Units", es:"Unidades", i:[["a piece of advice","un consejo"],["a slice of bread, a carton of milk","una rebanada de pan, un cartón de leche"]], ex:["Can I give you a piece of advice?","¿Puedo darte un consejo?"]},
  {e:"🔀", h:"Both uses", es:"Ambos usos", i:[["a coffee (a cup)","un café (una taza)"],["time / a time, hair / a hair","tiempo / una vez, pelo / un pelo"]], ex:["Two teas, please. I don't take sugar.","Dos tés, por favor. No tomo azúcar."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The advices are useful.","✓ The advice is useful. — sin plural, verbo singular"],["✗ My luggages are heavy.","✓ My luggage is heavy. — incontable"],["✗ I need an information.","✓ I need some information. — sin a/an"]], ex:["Her hair is long and the furniture is new.","Su pelo es largo y los muebles son nuevos."]}
 ], qs:[
  {q:"Choose: Your luggage ____ heavy. (is / are)", a:"is — luggage es incontable."},
  {q:"Fill in: Can I give you ____ advice? (a / some)", a:"some — advice es incontable; 'a piece of advice' también."},
  {q:"Correct the mistake: The news are terrible today.", a:"The news is terrible — singular."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"📐", t:"So / Such / Too / Enough", es:"So, such, too, enough", d:"Intensificar y expresar exceso o suficiencia.",
 boxes:[
  {e:"😮", h:"So + adjective", es:"So + adjetivo", i:[["so + adj / adverb","tan + adjetivo / adverbio"],["so + much / many","tanto / tantos"]], ex:["The film was so long that I fell asleep.","La película era tan larga que me dormí."]},
  {e:"🏙️", h:"Such + noun", es:"Such + nombre", i:[["such a + adj + noun","un + nombre + tan + adj"],["such + adj + plural","tan + adj + plural"]], ex:["It was such a lovely day.","Fue un día tan precioso."]},
  {e:"🔥", h:"Too", es:"Demasiado", i:[["too + adj","demasiado + adjetivo"],["too much / too many","demasiado / demasiados"]], ex:["It's too cold to sit outside.","Hace demasiado frío para sentarse fuera."]},
  {e:"✅", h:"Enough", es:"Suficiente", i:[["adj + enough","adjetivo + enough"],["enough + noun","enough + nombre"]], ex:["Is the room big enough for ten?","¿Es la sala lo bastante grande para diez?"]},
  {e:"🔗", h:"Result", es:"Resultado", i:[["so ... that","tan ... que"],["too ... to + verb","demasiado ... para + verbo"]], ex:["He's too tired to go out.","Está demasiado cansado para salir."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ It was so a nice day.","✓ It was such a nice day. — such + a + nombre"],["✗ I'm enough tired.","✓ I'm tired enough. — enough va después del adjetivo"],["✗ It's too much cold.","✓ It's too cold. — too + adjetivo, sin much"]], ex:["We haven't got enough time.","No tenemos suficiente tiempo."]}
 ], qs:[
  {q:"It was ____ a cold night that we stayed in. (so / such)", a:"such — such a + adj + nombre."},
  {q:"Choose: She isn't (enough old / old enough) to drive.", a:"old enough — enough tras el adjetivo."},
  {q:"Correct the mistake: It's too much hot in here.", a:"too hot — sin much."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"❓", t:"Question Forms (including subject & object questions)", es:"Formas de pregunta (sujeto y objeto)", d:"Cómo formar preguntas con auxiliares y cuándo no usar do.",
 boxes:[
  {e:"🔄", h:"Yes/No questions", es:"Preguntas de sí/no", i:[["Auxiliary + subject + verb","Auxiliar + sujeto + verbo"],["Do you live here?","¿Vives aquí?"]], ex:["Have you got a pen?","¿Tienes un bolígrafo?"]},
  {e:"🔎", h:"Wh- questions", es:"Preguntas con wh-", i:[["Wh- + auxiliary + subject","Wh- + auxiliar + sujeto"],["Where do you work?","¿Dónde trabajas?"]], ex:["What time does the shop open?","¿A qué hora abre la tienda?"]},
  {e:"🙋", h:"Subject questions", es:"Preguntas de sujeto", i:[["Who/What + verb (no do)","Who/What + verbo (sin do)"],["Who called you?","¿Quién te llamó?"]], ex:["Who lives next door?","¿Quién vive al lado?"]},
  {e:"🎯", h:"Object questions", es:"Preguntas de objeto", i:[["Who + auxiliary + subject + verb","Who + auxiliar + sujeto + verbo"],["Who did you call?","¿A quién llamaste?"]], ex:["Who did Tom invite to the party?","¿A quién invitó Tom a la fiesta?"]},
  {e:"🙊", h:"Polite indirect", es:"Preguntas indirectas corteses", i:[["Could you tell me where...?","¿Podría decirme dónde...?"],["Do you know what time...?","¿Sabes a qué hora...?"]], ex:["Could you tell me where the station is?","¿Podría decirme dónde está la estación?"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Where you live?","✓ Where do you live? — falta el auxiliar do"],["✗ Who did call you?","✓ Who called you? — pregunta de sujeto: sin did"],["✗ Can you tell me where is the station?","✓ ...where the station is? — orden afirmativo en indirectas"]], ex:["Who did you go on holiday with?","¿Con quién te fuiste de vacaciones?"]}
 ], qs:[
  {q:"Where ____ you ____ (go) last weekend?", a:"did / go — did + verbo base."},
  {q:"Choose: Who (broke / did break) the window?", a:"broke — sujeto: sin did."},
  {q:"Correct the mistake: Do you know where is the nearest chemist's?", a:"...where the nearest chemist's is? — orden de afirmativa."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🏷️", t:"Question Tags", es:"Question tags (¿verdad?, ¿no?)", d:"Preguntas cortas al final para confirmar o buscar acuerdo.",
 boxes:[
  {e:"➕", h:"Positive → negative", es:"Positivo → negativo", i:[["It's cold, isn't it?","Hace frío, ¿verdad?"],["You like tea, don't you?","Te gusta el té, ¿no?"]], ex:["It's a lovely day, isn't it?","Hace un día precioso, ¿verdad?"]},
  {e:"➖", h:"Negative → positive", es:"Negativo → positivo", i:[["You aren't tired, are you?","No estás cansado, ¿verdad?"],["He can't swim, can he?","No sabe nadar, ¿verdad?"]], ex:["You haven't seen my keys, have you?","No has visto mis llaves, ¿verdad?"]},
  {e:"🧱", h:"Auxiliary agrees", es:"El auxiliar concuerda", i:[["She's gone → hasn't she?","Se ha ido → tag con hasn't"],["They went → didn't they?","Fueron → tag con didn't"]], ex:["You live in Leeds, don't you?","Vives en Leeds, ¿no?"]},
  {e:"🎭", h:"Special cases", es:"Casos especiales", i:[["I am → aren't I?","Con I am se usa aren't I"],["Let's → shall we?","Con Let's se usa shall we (propuesta)"]], ex:["Let's go for a pint, shall we?","Vamos a tomar una cerveza, ¿te parece?"]},
  {e:"📈", h:"Rising vs falling", es:"Entonación", i:[["Rising ↗: real question","Ascendente ↗: pregunta real"],["Falling ↘: seeking agreement","Descendente ↘: buscar acuerdo"]], ex:["Lovely weather, isn't it? ↘","Qué buen tiempo, ¿verdad?"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ You like tea, isn't it?","✓ You like tea, don't you? — el tag repite el auxiliar"],["✗ You aren't tired, aren't you?","✓ You aren't tired, are you? — afirmación y tag de polaridad contraria"],["✗ I'm late, amn't I?","✓ I'm late, aren't I? — I am → aren't I"]], ex:["You're not coming, are you? ↗","No vienes, ¿verdad? (dudo)"]}
 ], qs:[
  {q:"You haven't been to Wales, ____ you?", a:"have — negativa lleva tag positivo."},
  {q:"Choose: She lives in York, (doesn't she / isn't she)?", a:"doesn't she — presente simple = do/does."},
  {q:"Correct the mistake: Let's have a cuppa, will we?", a:"shall we? — con Let's."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🤝", t:"So do I / Neither do I / Short Answers", es:"So do I, neither do I y respuestas cortas", d:"Mostrar acuerdo y responder de forma breve.",
 boxes:[
  {e:"👍", h:"So + auxiliary + I", es:"Yo también (afirmativo)", i:[["I love tea. – So do I.","Me encanta el té. – A mí también."],["I'm tired. – So am I.","Estoy cansado. – Yo también."]], ex:["I've been to Bath. – So have I.","He estado en Bath. – Yo también."]},
  {e:"👎", h:"Neither + auxiliary + I", es:"Yo tampoco", i:[["I don't like rain. – Neither do I.","No me gusta la lluvia. – A mí tampoco."],["Nor do I","Nor do I (igual, más formal)"]], ex:["I can't cook. – Neither can I.","No sé cocinar. – Yo tampoco."]},
  {e:"🔧", h:"Match the auxiliary", es:"Mismo auxiliar", i:[["I'm → am; I went → did","soy → am; fui → did"],["I can → can; I'll → will","puedo → can; haré → will"]], ex:["She went home. – So did he.","Se fue a casa. – Él también."]},
  {e:"🙅", h:"Me too / Me neither", es:"Informal", i:[["Me too","Yo también"],["Me neither","Yo tampoco"]], ex:["I'm starving. – Me too!","Me muero de hambre. – ¡Yo también!"]},
  {e:"💬", h:"Short answers", es:"Respuestas cortas", i:[["Yes, I do. / No, I don't.","Sí, (lo hago). / No, (no lo hago)."],["Yes, she has. / No, it isn't.","Sí, (lo ha hecho). / No, (no lo es)."]], ex:["Have you got a car? – Yes, I have.","¿Tienes auto? – Sí."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I like tea. – Me too like.","✓ I like tea. – So do I. — auxiliar + sujeto"],["✗ I don't like it. – So do I.","✓ I don't like it. – Neither do I. — negativo = neither"],["✗ Are you tired? – Yes, I tired.","✓ Yes, I am. — respuesta corta con auxiliar"]], ex:["I can swim. – Oh, I can't.","Sé nadar. – Yo no."]}
 ], qs:[
  {q:"I don't eat meat. – ____ do I.", a:"Neither — acuerdo negativo."},
  {q:"Choose: I've never been to Skye. – (So / Neither) have I.", a:"Neither — frase negativa."},
  {q:"Correct the mistake: Do you like jazz? – Yes, I like.", a:"Yes, I do. — respuesta corta con do."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"📍", t:"Adverbs: Position, Frequency & Degree", es:"Adverbios: posición, frecuencia y grado", d:"Dónde colocar los adverbios y cómo expresar frecuencia y grado.",
 boxes:[
  {e:"🏁", h:"End position", es:"Al final", i:[["Manner, place, time: at the end","Modo, lugar, tiempo: al final"],["manner → place → time","modo → lugar → tiempo"]], ex:["She drives carefully.","Maneja con cuidado."]},
  {e:"➡️", h:"Mid position", es:"Posición media", i:[["Before main verb","Antes del verbo principal"],["After be / auxiliary","Después de be / auxiliar"]], ex:["I've never been to Cornwall.","Nunca he estado en Cornualles."]},
  {e:"📊", h:"Frequency", es:"Frecuencia", i:[["always, usually, often","siempre, normalmente, a menudo"],["sometimes, rarely, never","a veces, rara vez, nunca"],["once a fortnight","una vez cada quince días"]], ex:["I usually go to work by Tube.","Normalmente voy al trabajo en metro."]},
  {e:"🌡️", h:"Degree", es:"Grado", i:[["very, quite, rather","muy, bastante, más bien"],["extremely, really, fairly","extremadamente, realmente, bastante"]], ex:["It's quite cold today.","Hace bastante frío hoy."]},
  {e:"🔝", h:"Front position", es:"Al principio", i:[["Luckily, ...","Por suerte, ..."],["Unfortunately, ...","Por desgracia, ..."]], ex:["Unfortunately, the museum was closed.","Por desgracia, el museo estaba cerrado."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I like very much tea.","✓ I like tea very much. — no entre verbo y objeto"],["✗ I don't never go there.","✓ I never go there. — never ya es negativo"],["✗ She speaks fluently English.","✓ She speaks English fluently. — adverbio tras el objeto"]], ex:["I hardly ever eat takeaways.","Casi nunca como comida para llevar."]}
 ], qs:[
  {q:"Put the adverb: I (always) ____ drink tea in the morning.", a:"I always drink tea — antes del verbo principal."},
  {q:"Choose: She is (always late / late always).", a:"always late — tras be."},
  {q:"Correct the mistake: I don't never eat meat.", a:"I never eat meat. — doble negación."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🎨", t:"Order of Adjectives", es:"Orden de los adjetivos", d:"El orden natural cuando usamos varios adjetivos.",
 boxes:[
  {e:"📋", h:"The order", es:"El orden", i:[["Opinion → size → age","Opinión → tamaño → edad"],["shape → colour → origin","forma → color → origen"],["material → noun","material → nombre"]], ex:["a lovely old stone cottage","una preciosa casita antigua de piedra"]},
  {e:"💬", h:"Opinion first", es:"Opinión primero", i:[["lovely, awful, delicious","precioso, horrible, delicioso"],["a delicious Italian pizza","una deliciosa pizza italiana"]], ex:["She has a beautiful long dress.","Tiene un vestido largo precioso."]},
  {e:"📏", h:"Size, age, shape", es:"Tamaño, edad, forma", i:[["big, small, tall","grande, pequeño, alto"],["new, old, round","nuevo, viejo, redondo"]], ex:["He bought a big old round table.","Compró una gran mesa redonda antigua."]},
  {e:"🌈", h:"Colour, origin", es:"Color, origen", i:[["red, blue","rojo, azul"],["British, Welsh, Spanish","británico, galés, español"]], ex:["She wore a red Scottish tartan scarf.","Llevaba una bufanda escocesa de tartán roja."]},
  {e:"✂️", h:"Use of 'and'", es:"Uso de and", i:[["Two colours: black and white","Dos colores: se unen con and"],["After linking verbs: and","Tras ser/estar: and antes del último"]], ex:["The house was big, old and cold.","La casa era grande, vieja y fría."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ a wooden small box","✓ a small wooden box — tamaño antes que material"],["✗ a car red","✓ a red car — el adjetivo va antes del nombre"],["✗ a blues eyes girl","✓ a blue-eyed girl — adjetivo sin plural"]], ex:["I love my little wooden tea box.","Me encanta mi cajita de madera para el té."]}
 ], qs:[
  {q:"Order: a (wooden / small / lovely) box.", a:"a lovely small wooden box — opinión, tamaño, material."},
  {q:"Choose: a (French old / old French) castle.", a:"old French — edad antes que origen."},
  {q:"Correct the mistake: She bought a leather black new jacket.", a:"a new black leather jacket — edad, color, material."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"🕐", t:"Prepositions of Time & Place (in, on, at)", es:"Preposiciones de tiempo y lugar", d:"Usar in, on y at con fechas, horas y lugares.",
 boxes:[
  {e:"🕒", h:"At: time", es:"At: hora", i:[["at 9 o'clock, at noon","a las 9, al mediodía"],["at night, at the weekend (UK)","por la noche, el fin de semana"]], ex:["The train leaves at 17:45.","El tren sale a las 17:45."]},
  {e:"📅", h:"On: days & dates", es:"On: días y fechas", i:[["on Monday, on 5th May","el lunes, el 5 de mayo"],["on Friday evening","el viernes por la tarde"]], ex:["We're meeting on Saturday.","Nos vemos el sábado."]},
  {e:"🗓️", h:"In: periods", es:"In: periodos", i:[["in May, in 2024, in winter","en mayo, en 2024, en invierno"],["in the morning","por la mañana"]], ex:["I was born in March.","Nací en marzo."]},
  {e:"📍", h:"At: points", es:"At: puntos", i:[["at the bus stop, at home","en la parada, en casa"],["at the station, at work","en la estación, en el trabajo"]], ex:["I'll meet you at the station.","Te veo en la estación."]},
  {e:"🛣️", h:"On / in: place", es:"On / in: lugar", i:[["on the table, on the Tube","en la mesa, en el metro"],["in London, in a room, in hospital","en Londres, en una sala, ingresado"]], ex:["I read on the Tube every day.","Leo en el metro cada día."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I'll see you in Monday.","✓ I'll see you on Monday. — días con on"],["✗ I get up in 7 o'clock.","✓ I get up at 7 o'clock. — hora con at"],["✗ I live at London.","✓ I live in London. — ciudades con in"]], ex:["She works in a bank in Leeds.","Trabaja en un banco de Leeds."]}
 ], qs:[
  {q:"I'll see you ____ Friday ____ 6 pm. (on / at)", a:"on / at — día + hora exacta."},
  {q:"Choose: We go skiing (in / on) winter.", a:"in — estaciones con in."},
  {q:"Correct the mistake: She arrived in the station at 5 o'clock.", a:"at the station — punto de encuentro."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🔗", t:"Dependent Prepositions (interested in, good at, afraid of)", es:"Preposiciones dependientes", d:"Adjetivos, verbos y nombres que exigen una preposición concreta.",
 boxes:[
  {e:"😃", h:"Adjective + in/at", es:"Adjetivo + in/at", i:[["interested in","interesado en"],["good / bad at","bueno / malo en"]], ex:["I'm interested in history and good at maths.","Me interesa la historia y soy bueno para las matemáticas."]},
  {e:"😨", h:"Adjective + of", es:"Adjetivo + of", i:[["afraid of, scared of","miedo de"],["proud of, tired of","orgulloso de, harto de"]], ex:["She's afraid of spiders.","Tiene miedo de las arañas."]},
  {e:"🤝", h:"Adjective + with/about", es:"With / about", i:[["bored with / fed up with","aburrido de / harto de"],["worried about, excited about","preocupado por, emocionado por"]], ex:["I'm fed up with the rain.","Estoy harto de la lluvia."]},
  {e:"🏃", h:"Verb + preposition", es:"Verbo + preposición", i:[["depend on, rely on","depender de, confiar en"],["listen to, wait for","escuchar, esperar"]], ex:["It depends on the weather.","Depende del tiempo."]},
  {e:"💬", h:"Verb + to/for", es:"To / for", i:[["apologise for","disculparse por"],["apply for a job","solicitar un empleo"]], ex:["I apologised for being late.","Me disculpé por llegar tarde."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I'm interested on music.","✓ I'm interested in music. — interested in"],["✗ She's good in maths.","✓ She's good at maths. — good at"],["✗ I depend of my parents.","✓ I depend on my parents. — depend on"],["✗ I'm afraid to dogs.","✓ I'm afraid of dogs. — afraid of"]], ex:["She's keen on learning Welsh.","Le entusiasma aprender galés."]}
 ], qs:[
  {q:"I'm not very good ____ drawing. (in / at)", a:"at — good at + -ing."},
  {q:"Choose: We're waiting (for / to) the bus.", a:"for — wait for."},
  {q:"Correct the mistake: She is married with a doctor.", a:"married to a doctor — married to."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🔃", t:"Inversion (Never have I…, Not only… but also…)", es:"Inversión (Never have I…, Not only… but also…)", d:"Invertir sujeto y auxiliar tras adverbios negativos para dar énfasis.",
 boxes:[
  {e:"🚫", h:"Negative adverbs", es:"Adverbios negativos", i:[["Never / Rarely / Seldom + auxiliary + subject","Never / Rarely / Seldom + auxiliar + sujeto"],["Never have I seen...","Nunca he visto..."]], ex:["Never have I eaten such good fish and chips.","Nunca he comido unos fish and chips tan buenos."]},
  {e:"➕", h:"Not only … but also", es:"No solo … sino también", i:[["Not only + auxiliary + subject","Not only + auxiliar + sujeto"],["...but also + clause","...but also + oración"]], ex:["Not only did he arrive late, but he also forgot his ticket.","No solo llegó tarde, sino que olvidó su boleto."]},
  {e:"⏱️", h:"No sooner … than", es:"Apenas … cuando", i:[["No sooner had I + p.p. ... than","Apenas había + participio ... cuando"],["Hardly had I ... when","Hardly had I ... when (apenas ... cuando)"]], ex:["No sooner had we sat down than it started to rain.","Apenas nos sentamos, empezó a llover."]},
  {e:"🔒", h:"Only + time/condition", es:"Only + tiempo o condición", i:[["Only then / Only after + inversion","Only then / Only after + inversión"],["Only when I got home did I...","Solo cuando llegué a casa..."]], ex:["Only after the match did I realise I'd lost my phone.","Solo después del partido me di cuenta de que había perdido el celular."]},
  {e:"🧠", h:"Little, under no circumstances", es:"Otras expresiones", i:[["Little did I know...","Poco sabía yo..."],["Under no circumstances should you...","En ningún caso debes..."]], ex:["Little did she know that the bus had gone.","Poco sabía ella que el autobús ya se había ido."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Never I have seen it.","✓ Never have I seen it. — se invierte auxiliar y sujeto"],["✗ Not only he came late...","✓ Not only did he come late... — hace falta did"],["✗ Rarely does he goes out.","✓ Rarely does he go out. — verbo base tras does"]], ex:["Rarely do we eat out during the week.","Rara vez comemos fuera entre semana."]}
 ], qs:[
  {q:"Never ____ I ____ (see) such a beautiful view.", a:"have / seen — Never have I seen."},
  {q:"Choose: Not only (he was / was he) rude, but he was also late.", a:"was he — inversión tras Not only."},
  {q:"Correct the mistake: Hardly I had arrived when it started to rain.", a:"Hardly had I arrived... — inversión."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🎯", t:"Cleft Sentences (It was… that / What I need is…)", es:"Oraciones hendidas (It was… that / What I need is…)", d:"Poner énfasis en una parte de la frase con it o what.",
 boxes:[
  {e:"👉", h:"It-cleft", es:"Con It", i:[["It was + focus + that / who + clause","It was + foco + that / who + oración"],["It was Tom who broke it.","Fue Tom quien lo rompió."]], ex:["It was in Brighton that we first met.","Fue en Brighton donde nos conocimos."]},
  {e:"❓", h:"What-cleft", es:"Con What", i:[["What + clause + is / was + focus","What + oración + is / was + foco"],["What I need is a cup of tea.","Lo que necesito es una taza de té."]], ex:["What annoys me is the noise.","Lo que me molesta es el ruido."]},
  {e:"🔍", h:"Emphasising time and place", es:"Énfasis en tiempo y lugar", i:[["It was last year that...","Fue el año pasado cuando..."],["It was at Victoria that...","Fue en Victoria donde..."]], ex:["It was last winter that I moved to Leeds.","Fue el invierno pasado cuando me mudé a Leeds."]},
  {e:"🛠️", h:"All / The thing", es:"All / The thing", i:[["All I want is some peace.","Todo lo que quiero es algo de paz."],["The thing I like is...","Lo que me gusta es..."]], ex:["All I did was ask a question.","Solo hice una pregunta."]},
  {e:"🔄", h:"Reverse what-cleft", es:"What-cleft invertida", i:[["A cup of tea is what I need.","Una taza de té es lo que necesito."],["That's what I mean.","Eso es lo que quiero decir."]], ex:["A holiday is exactly what you need.","Unas vacaciones son justo lo que necesitas."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ It was Tom who he broke it.","✓ It was Tom who broke it. — no repetir el sujeto"],["✗ What I need it is a rest.","✓ What I need is a rest. — sin pronombre extra"],["✗ It is yesterday that I came.","✓ It was yesterday that I came. — tiempo del verbo coherente"]], ex:["What I love about Wales is the scenery.","Lo que me encanta de Gales es el paisaje."]}
 ], qs:[
  {q:"____ I need is a long holiday.", a:"What — lo que necesito es..."},
  {q:"Choose: It was my brother (who / what) broke the window.", a:"who — it-cleft con persona."},
  {q:"Correct the mistake: What annoys me it is the queue.", a:"What annoys me is the queue. — sin it."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"✅", t:"Participle Clauses (Having finished…, Seen from…)", es:"Cláusulas de participio (Having finished…, Seen from…)", d:"Acortar oraciones con participios para escribir de forma más fluida.",
 boxes:[
  {e:"🏃", h:"Present participle", es:"Participio de presente", i:[["Walking home, I saw...","Mientras caminaba a casa, vi..."],["Feeling tired, she went to bed.","Sintiéndose cansada, se fue a la cama."]], ex:["Walking along the Thames, I met an old friend.","Paseando por el Támesis, me encontré con un viejo amigo."]},
  {e:"⏮️", h:"Perfect participle", es:"Participio perfecto", i:[["Having + p.p. = earlier action","Having + p.p. = acción anterior"],["Having finished, I left.","Habiendo terminado, me fui."]], ex:["Having missed the train, we took a taxi.","Al haber perdido el tren, tomamos un taxi."]},
  {e:"📬", h:"Past participle", es:"Participio pasado", i:[["Seen from here, it looks small.","Visto desde aquí, parece pequeño."],["Tired after work, he slept.","Cansado tras el trabajo, durmió."]], ex:["Built in 1850, the bridge is still in use.","Construido en 1850, el puente sigue en uso."]},
  {e:"🔗", h:"Same subject rule", es:"Mismo sujeto", i:[["Subject of both clauses is the same","El sujeto de ambas partes es el mismo"],["Reason, time, result","Causa, tiempo, resultado"]], ex:["Opening the door, she saw a parcel.","Al abrir la puerta, vio un paquete."]},
  {e:"🚫", h:"Negative & with conjunctions", es:"Negativo y con conjunciones", i:[["Not knowing the way, ...","Al no saber el camino, ..."],["After / while / before + -ing","Después de / mientras / antes de + -ing"]], ex:["Not wanting to be late, I ran.","No queriendo llegar tarde, corrí."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Walking home, the rain started.","✓ Walking home, I got caught in the rain. — mismo sujeto (dangling)"],["✗ Finished the work, I left.","✓ Having finished the work, I left. — acción anterior = having + p.p."],["✗ Seeing from the hill, the town looks small.","✓ Seen from the hill, the town looks small. — sentido pasivo = participio pasado"]], ex:["Having lived in London, he knows the Tube well.","Habiendo vivido en Londres, conoce bien el metro."]}
 ], qs:[
  {q:"____ (finish) my homework, I watched telly.", a:"Having finished — acción anterior."},
  {q:"Choose: (Walking / Walked) down the road, I found a tenner.", a:"Walking — acción simultánea."},
  {q:"Correct the mistake: Opening the door, the cat ran out.", a:"Opening the door, I saw the cat run out. — mismo sujeto."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B1", icon:"👥", t:"Determiners: each, every, all, both, either, neither", es:"Determinantes: each, every, all, both, either, neither", d:"Hablar de grupos y de dos elementos con determinantes distintos.",
 boxes:[
  {e:"1️⃣", h:"Each", es:"Cada uno", i:[["each + singular noun","each + nombre singular"],["each of the + plural","cada uno de los + plural"]], ex:["Each student gets a certificate.","Cada alumno recibe un certificado."]},
  {e:"🔁", h:"Every", es:"Cada / todos", i:[["every + singular noun","every + nombre singular"],["every day, every other week","cada día, cada dos semanas"]], ex:["Every flat in this block has a balcony.","Todos los apartamentos de este edificio tienen balcón."]},
  {e:"💯", h:"All", es:"Todo / todos", i:[["all + plural / uncountable","all + plural / incontable"],["all of them, all day","todos ellos, todo el día"]], ex:["All the shops close at six.","Todas las tiendas cierran a las seis."]},
  {e:"✌️", h:"Both", es:"Ambos", i:[["both + plural noun","both + nombre plural"],["both of us, both ... and","los dos, tanto ... como"]], ex:["Both my parents are teachers.","Mis dos padres son profesores."]},
  {e:"🔀", h:"Either / Neither", es:"Uno u otro / ninguno", i:[["either: one of two","either: uno de los dos"],["neither: not one, not the other","neither: ni uno ni otro"]], ex:["Neither team played well.","Ninguno de los dos equipos jugó bien."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Every students are here.","✓ Every student is here. — every + singular"],["✗ All of my friends is nice.","✓ All of my friends are nice. — all + plural"],["✗ Both of them doesn't like it.","✓ Neither of them likes it. — para negar dos, neither"]], ex:["You can take either road; both lead to Bath.","Puedes tomar cualquiera de las dos carreteras; ambas llevan a Bath."]}
 ], qs:[
  {q:"____ student has to bring a pencil. (Every / All)", a:"Every — singular."},
  {q:"Choose: (Neither / None) of the two answers is correct.", a:"Neither — solo dos."},
  {q:"Correct the mistake: All the milk have gone off.", a:"All the milk has gone off. — milk es incontable."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"B2", icon:"🤔", t:"Would rather, It's time, Had better & Prefer", es:"Would rather, It's time, Had better y Prefer", d:"Preferencias, consejos fuertes y la idea de que ya es hora de algo.",
 boxes:[
  {e:"💭", h:"Would rather + verb", es:"Preferiría + verbo", i:[["I'd rather + base verb","I'd rather + verbo base"],["I'd rather not go.","Preferiría no ir."]], ex:["I'd rather stay in tonight.","Preferiría quedarme en casa esta noche."]},
  {e:"👤", h:"Would rather + person", es:"Preferiría que alguien...", i:[["I'd rather you + past simple","I'd rather you + pasado simple"],["Present/future meaning","Significado de presente o futuro"]], ex:["I'd rather you didn't smoke in here.","Preferiría que no fumaras aquí."]},
  {e:"⏰", h:"It's time", es:"Ya es hora de", i:[["It's time + past simple","It's time + pasado simple"],["It's time to + verb","It's time to + verbo"]], ex:["It's time we went home.","Ya es hora de que nos vayamos a casa."]},
  {e:"💪", h:"Had better", es:"Más vale que", i:[["had better + base verb","had better + verbo base"],["had better not + base verb","had better not + verbo base"]], ex:["You'd better leave now or you'll miss the train.","Más vale que te vayas ya o perderás el tren."]},
  {e:"❤️", h:"Prefer", es:"Preferir", i:[["prefer X to Y","preferir X a Y"],["prefer + -ing / to + verb","preferir + -ing / to + verbo"]], ex:["I prefer tea to coffee.","Prefiero el té al café."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I'd rather to stay at home.","✓ I'd rather stay at home. — sin to"],["✗ It's time to we leave.","✓ It's time we left. — pasado simple, o time to leave"],["✗ I prefer tea than coffee.","✓ I prefer tea to coffee. — prefer X to Y"],["✗ You had better to go.","✓ You had better go. — sin to"]], ex:["I'd rather walk than take the bus.","Prefiero caminar a tomar el autobús."]}
 ], qs:[
  {q:"It's time we ____ (go) home.", a:"went — it's time + pasado simple."},
  {q:"Choose: I'd rather (to stay / stay) in tonight.", a:"stay — would rather + verbo base."},
  {q:"Correct the mistake: I prefer walking than driving.", a:"I prefer walking to driving. — prefer X to Y."}
 ] }
]);
